home.css:
/* Furnisite Home Styles */
.furnisite-hero { position: relative; min-height: 560px; display: flex; align-items: center; justify-content: center; overflow: hidden; background-color: #f4f1ea; }
.furnisite-hero-bg { position: absolute; inset: 0; z-index: 1; }
.furnisite-hero-img { width: 100%; height: 100%; object-fit: cover; object-position: center 38%; display: block; }
.furnisite-hero-overlay { position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(20, 20, 22, 0.45) 0%, rgba(20, 20, 22, 0.25) 50%, rgba(20, 20, 22, 0.55) 100%); }
.furnisite-hero-content-wrap { position: relative; z-index: 2; padding: 60px 24px; text-align: center; width: 100%; max-width: 1240px; margin: 0 auto; }
.furnisite-hero-content { max-width: 680px; margin: 0 auto; text-align: center; color: #ffffff; }
.furnisite-hero-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 3.5rem; font-weight: 800; color: #ffffff; line-height: 1.15; letter-spacing: -0.5px; margin-bottom: 16px; text-shadow: 0 2px 10px rgba(0, 0, 0, 0.2); }
.furnisite-hero-subtitle { font-family: 'Inter', sans-serif; font-size: 1.15rem; font-weight: 400; color: rgba(255, 255, 255, 0.92); margin-bottom: 28px; line-height: 1.6; text-shadow: 0 1px 6px rgba(0, 0, 0, 0.25); }
.furnisite-hero-actions { display: flex; justify-content: center; }
.furnisite-hero-btn { display: inline-flex; align-items: center; justify-content: center; background-color: #18181b; color: #ffffff; padding: 14px 34px; border-radius: 4px; font-weight: 600; font-size: 0.95rem; text-decoration: none; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.2); }
.furnisite-products-section { padding: 90px 0; background-color: #ffffff; }
.furnisite-products-layout { display: grid; grid-template-columns: 280px 1fr; gap: 56px; align-items: start; }
.furnisite-intro-box { display: flex; flex-direction: column; justify-content: flex-start; }
.furnisite-section-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.3rem; font-weight: 700; line-height: 1.2; color: #18181b; margin-bottom: 20px; letter-spacing: -0.5px; }
.furnisite-section-desc { font-family: 'Inter', sans-serif; font-size: 0.95rem; color: #52525b; line-height: 1.65; margin-bottom: 28px; }
.furnisite-intro-action { display: flex; }
.furnisite-products-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.furnisite-product-card { display: flex; flex-direction: column; background: #ffffff; border-radius: 6px; overflow: hidden; }
.furnisite-card-image-link { display: block; text-decoration: none; }
.furnisite-card-image-wrap { position: relative; background-color: #f7f6f2; border-radius: 4px; aspect-ratio: 1 / 1; overflow: hidden; display: flex; align-items: center; justify-content: center; margin-bottom: 14px; }
.furnisite-card-img { width: 100%; height: 100%; object-fit: cover; object-position: center; display: block; }
.furnisite-card-arrow { position: absolute; right: 12px; bottom: 10px; font-size: 1.1rem; color: #18181b; font-weight: 600; }
.furnisite-card-meta { display: flex; flex-direction: column; gap: 4px; }
.furnisite-card-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 0.98rem; font-weight: 600; color: #18181b; margin: 0; line-height: 1.35; }
.furnisite-card-title a { color: inherit; text-decoration: none; }
.furnisite-card-price { font-family: 'Inter', sans-serif; font-size: 0.92rem; font-weight: 700; color: #52525b; margin: 0; }
.furnisite-vision-section { padding: 90px 0; background-color: #faf9f6; }
.furnisite-vision-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 48px; }
.furnisite-vm-card { display: flex; flex-direction: column; gap: 24px; }
.furnisite-vm-header { display: flex; flex-direction: column; gap: 12px; }
.furnisite-vm-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.1rem; font-weight: 700; color: #18181b; margin: 0; letter-spacing: -0.5px; }
.furnisite-vm-text { font-family: 'Inter', sans-serif; font-size: 1rem; color: #52525b; line-height: 1.7; margin: 0; }
.furnisite-vm-image-wrap { width: 100%; aspect-ratio: 4 / 3; overflow: hidden; border-radius: 6px; background-color: #f0eee6; }
.furnisite-vm-img { width: 100%; height: 100%; object-fit: cover; object-position: center; display: block; }
.furnisite-team-section { padding: 90px 0; background-color: #ffffff; }
.furnisite-team-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.2rem; font-weight: 700; text-align: center; margin-bottom: 48px; color: #18181b; letter-spacing: -0.5px; }
.furnisite-team-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.furnisite-team-card { display: flex; flex-direction: column; text-align: center; }
.furnisite-team-avatar-wrap { width: 100%; aspect-ratio: 1 / 1.15; background-color: #f4f4f5; border-radius: 4px; overflow: hidden; margin-bottom: 14px; }
.furnisite-team-img { width: 100%; height: 100%; object-fit: cover; object-position: center top; display: block; }
.furnisite-member-name { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 1.05rem; font-weight: 700; color: #18181b; margin: 0 0 4px 0; }
.furnisite-member-role { font-family: 'Inter', sans-serif; font-size: 0.85rem; color: #71717a; margin: 0; }

about.css:
/* Furnisite About Styles */
.fs-about-hero { padding-top: 72px; padding-bottom: 56px; background-color: #ffffff; text-align: center; }
.fs-about-hero-inner { max-width: 780px; margin: 0 auto; }
.fs-about-hero-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.5rem; font-weight: 800; line-height: 1.2; color: #18181b; margin: 16px 0; letter-spacing: -0.5px; }
@media (min-width: 768px) { .fs-about-hero-title { font-size: 3.2rem; } }
.fs-about-hero-lead { font-family: 'Inter', sans-serif; font-size: 1.1rem; color: #52525b; line-height: 1.7; margin: 0; }
.fs-about-banner-wrap { margin-bottom: 72px; }
.fs-about-banner { border-radius: 8px; overflow: hidden; aspect-ratio: 21 / 9; background-color: #f4f1ea; }
.fs-about-banner-img { width: 100%; height: 100%; object-fit: cover; display: block; }
.fs-pillars-section { padding-bottom: 80px; background-color: #ffffff; }
.fs-pillars-grid { display: grid; grid-template-columns: 1fr; gap: 32px; }
@media (min-width: 640px) { .fs-pillars-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .fs-pillars-grid { grid-template-columns: repeat(4, 1fr); gap: 28px; } }
.fs-pillar-card { background-color: #faf9f6; padding: 32px 24px; border-radius: 6px; border: 1px solid #f0eee6; display: flex; flex-direction: column; gap: 12px; }
.fs-pillar-icon { font-size: 2rem; display: inline-block; }
.fs-pillar-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 1.05rem; font-weight: 700; color: #18181b; margin: 0; line-height: 1.35; }
.fs-pillar-desc { font-family: 'Inter', sans-serif; font-size: 0.88rem; color: #71717a; line-height: 1.6; margin: 0; }
.fs-about-cta-section { padding-top: 80px; padding-bottom: 100px; background-color: #faf9f6; text-align: center; }
.fs-about-cta-box { max-width: 680px; margin: 0 auto; }
.fs-about-cta-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.2rem; font-weight: 800; color: #18181b; margin-bottom: 14px; letter-spacing: -0.5px; }
.fs-about-cta-desc { font-family: 'Inter', sans-serif; font-size: 1.02rem; color: #71717a; margin-bottom: 32px; line-height: 1.6; }
.fs-about-cta-actions { display: flex; justify-content: center; gap: 16px; flex-wrap: wrap; }

blog.css:
/* Furnisite Journal Styles */
.fs-journal-hero { padding-top: 72px; padding-bottom: 56px; background-color: #faf9f6; text-align: center; border-bottom: 1px solid #f0eee6; }
.fs-journal-hero-inner { max-width: 680px; margin: 0 auto; }
.fs-journal-hero-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.5rem; font-weight: 800; color: #18181b; margin: 12px 0; letter-spacing: -0.5px; }
@media (min-width: 768px) { .fs-journal-hero-title { font-size: 3.2rem; } }
.fs-journal-hero-subtitle { font-family: 'Inter', sans-serif; font-size: 1.05rem; color: #52525b; line-height: 1.6; margin: 0; }
.fs-journal-main { padding-top: 64px; padding-bottom: 96px; background-color: #ffffff; }
.fs-journal-grid { display: grid; grid-template-columns: 1fr; gap: 48px; }
@media (min-width: 640px) { .fs-journal-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .fs-journal-grid { grid-template-columns: repeat(3, 1fr); gap: 40px; } }
.fs-post-card { display: flex; flex-direction: column; background-color: #ffffff; }
.fs-post-thumb-link { display: block; text-decoration: none; margin-bottom: 16px; }
.fs-post-thumb-wrap { aspect-ratio: 16 / 10; overflow: hidden; border-radius: 6px; background-color: #f4f4f5; }
.fs-post-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s ease; display: block; }
.fs-post-card:hover .fs-post-img { transform: scale(1.04); }
.fs-post-content { display: flex; flex-direction: column; flex: 1; }
.fs-post-meta { display: flex; align-items: center; gap: 6px; font-size: 0.78rem; color: #a1a1aa; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 10px; }
.fs-post-cat { color: #18181b; font-weight: 600; }
.fs-post-time { color: #a1a1aa; }
.fs-post-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 1.25rem; font-weight: 700; line-height: 1.35; color: #18181b; margin: 0 0 10px 0; }
.fs-post-title a { color: inherit; text-decoration: none; }
.fs-post-excerpt { font-family: 'Inter', sans-serif; font-size: 0.92rem; color: #71717a; line-height: 1.6; margin-bottom: 18px; flex: 1; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.fs-post-more-link { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 0.88rem; font-weight: 600; color: #18181b; display: inline-flex; align-items: center; gap: 6px; text-decoration: none; }

contact.css:
/* Furnisite Contact Styles */
.fs-contact-hero { padding-top: 72px; padding-bottom: 56px; background-color: #faf9f6; text-align: center; border-bottom: 1px solid #f0eee6; }
.fs-contact-hero-inner { max-width: 680px; margin: 0 auto; }
.fs-contact-hero-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 2.5rem; font-weight: 800; color: #18181b; margin: 14px 0; letter-spacing: -0.5px; }
@media (min-width: 768px) { .fs-contact-hero-title { font-size: 3.2rem; } }
.fs-contact-hero-lead { font-family: 'Inter', sans-serif; font-size: 1.05rem; color: #52525b; line-height: 1.6; margin: 0; }
.fs-contact-main { padding-top: 72px; padding-bottom: 96px; background-color: #ffffff; }
.fs-contact-grid { display: grid; grid-template-columns: 1fr; gap: 48px; }
@media (min-width: 992px) { .fs-contact-grid { grid-template-columns: 1.4fr 1fr; gap: 64px; } }
.fs-contact-form-wrap { background-color: #ffffff; border-radius: 8px; }
.fs-form-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 1.75rem; font-weight: 700; color: #18181b; margin-bottom: 8px; }
.fs-form-desc { font-family: 'Inter', sans-serif; font-size: 0.92rem; color: #71717a; margin-bottom: 28px; }
.fs-contact-form { display: flex; flex-direction: column; gap: 20px; }
.fs-form-row { display: grid; grid-template-columns: 1fr; gap: 20px; }
@media (min-width: 600px) { .fs-form-row { grid-template-columns: repeat(2, 1fr); } }
.fs-form-group { display: flex; flex-direction: column; gap: 8px; }
.fs-form-group label { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 0.88rem; font-weight: 600; color: #27272a; }
.fs-form-group input, .fs-form-group select, .fs-form-group textarea { padding: 12px 14px; border: 1px solid #e4e4e7; background-color: #faf9f6; border-radius: 4px; font-family: 'Inter', sans-serif; font-size: 0.95rem; color: #18181b; outline: none; }
.fs-contact-sidebar { display: flex; flex-direction: column; gap: 24px; }
.fs-info-card { background-color: #faf9f6; border: 1px solid #f0eee6; border-radius: 6px; padding: 32px; }
.fs-info-card-title { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 1.25rem; font-weight: 700; color: #18181b; margin-bottom: 12px; }
.fs-info-sub { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 0.92rem; font-weight: 700; color: #27272a; text-transform: uppercase; letter-spacing: 0.5px; margin-top: 14px; margin-bottom: 8px; }
.fs-info-line { font-family: 'Inter', sans-serif; font-size: 0.92rem; color: #52525b; margin-bottom: 6px; line-height: 1.5; }
.fs-info-divider { height: 1px; background-color: #e7e5e0; margin: 18px 0; }
.fs-contact-channel { display: flex; flex-direction: column; gap: 2px; margin-bottom: 14px; }
.fs-channel-label { font-size: 0.82rem; color: #71717a; font-weight: 500; }
.fs-channel-val { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 0.95rem; font-weight: 600; color: #18181b; text-decoration: none; }
